-- WorkoutApp seed, part 6 of 7
-- Tables: nutrition_days, food_entries
-- Run parts in order; each is idempotent (upsert), safe to re-run.

on conflict (id) do update set client_id=excluded.client_id,date=excluded.date,target_calories=excluded.target_calories,target_protein=excluded.target_protein,target_carbs=excluded.target_carbs,target_fat=excluded.target_fat,consumed_calories=excluded.consumed_calories,consumed_protein=excluded.consumed_protein,consumed_carbs=excluded.consumed_carbs,consumed_fat=excluded.consumed_fat;

on conflict (id) do update set nutrition_day_id=excluded.nutrition_day_id,client_id=excluded.client_id,date=excluded.date,slot=excluded.slot,food_id=excluded.food_id,name=excluded.name,servings=excluded.servings,calories=excluded.calories,protein=excluded.protein,carbs=excluded.carbs,fat=excluded.fat,source=excluded.source,logged_at=excluded.logged_at;
